function db.weatherStrength(Rl)
local Sl=db.fx(Rl)
local Tl=Sl.dmg/Sl.cd/Sl.hp/Sl.speed*(1+(Sl.range-1)/2)
for Ul,Vl in pairs(Sl.kinds)do
Tl=Tl*(1+P.rogueShare(Ul)*Vl)
end
if Sl.ice>0 then
local Wl=P.rogueShare(hlc[1552])
Tl=Tl*(Wl+(1-Wl)/(1-Sl.ice+Sl.ice/V.modFactor(hlc[1581])))
end
if Sl.fly>0 then
Tl=Tl*(1-Sl.fly*0.5)
end
if Sl.noCC then
Tl=Tl*0.95
end
if Sl.shroud then
Tl=Tl*0.9
end
return Tl
end
function db.cardGems(Xl,Yl)
