function db.skinTick()
if not(H.skinSmart or H.starOpen)or not(I.live.event and db.is(I.live.event.level))then
return
end
if(j.req.back.skins or 0)>L.now()then
return
end
local Nn=G.session()
local function On(Pn,Qn,Rn)
local Sn=j.gameSaid(Qn)
O.pickNote.skins=string.format(hlc[1627],Pn,tostring(Sn or Rn or hlc[1628]))
j.log(1,hlc[1569],O.pickNote.skins)
j.backoff(hlc[1629],1800)
end
local Tn=db.skinPlan()
if H.skinSmart then
local Un=Tn.wear[1]
if Un and(j.req.back.skinWear or 0)<=L.now()then
local Vn=cb.slotOf(Un.unit)
if Vn then
I.str.reequip={uuid=Un.unit,slot=Vn}
j.saveNow()
j.request(hlc[1630],hlc[1631],Un.unit)
local Wn=L.now()
while L.now()-Wn<4 and cb.slotOf(Un.unit)do
task.wait(0.25)
end
end
local Xn=L.now()
local Yn,Zn=j.request(hlc[1632],hlc[1633],Un.uuid,{unit_uuid=Un.unit})
local function ao()
local bo=Nn.collection:get_unit_by_uuid(Un.unit)
return bo and bo.skin~=nil
end
while L.now()-Xn<5 and not ao()do
task.wait(0.25)
end
if Vn then
cb.reequip()
end
if ao()then
j.log(1,hlc[1569],string.format(hlc[1634],Un.name,Un.unitName))
O.pickNote.skins=nil
Tn=db.skinPlan()
else
local co=j.gameSaid(Xn)
O.pickNote.skins=string.format(hlc[1635],Un.name,tostring(co or Zn or hlc[1628]))
j.log(1,hlc[1569],O.pickNote.skins)
j.backoff(hlc[1632],1800)
end
end
if#Tn.sell>0 then
local eo,fo={},0
for go=1,math.min(50,#Tn.sell)do
table.insert(eo,Tn.sell[go].uuid)
fo=fo+Tn.sell[go].pearls
end
local ho=tonumber(G.cur(hlc[1600]))or 0
local io=L.now()
local jo,ko=j.request(hlc[1636],hlc[1637],eo)
while L.now()-io<5 and(tonumber(G.cur(hlc[1600]))or 0)<=ho do
task.wait(0.25)
end
local mo=(tonumber(G.cur(hlc[1600]))or 0)-ho
if mo<=0 then
return On(hlc[1638],io,ko)
end
Q.add(string.format(hlc[1639],#eo),#eo,hlc[1629],string.format(hlc[1640],L.fmt(mo)))
O.pickNote.skins=nil
end
end
if H.starOpen then
local no=Nn.inventory
local function oo()
local po,qo=pcall(no.get_number_of_owned_item,no,db.STAR)
return po and tonumber(qo)or 0
end
local ro=L.now()
for so=1,8 do
if L.now()-ro>15 or not j.alive or j.where~=hlc[1444]then
break
end
local uo=oo()
local vo=db.starPlan(db.skinPlan())
local wo=L.now()
if uo>0 then
local xo,yo=j.request(hlc[1641],hlc[1642],db.STAR,{use10=uo>=10,use_all=false})
while L.now()-wo<6 and oo()>=uo do
task.wait(0.25)
end
if oo()>=uo then
return On(hlc[1643],wo,yo)
end
j.log(1,hlc[1569],string.format(hlc[1644],uo-oo(),(tonumber(((G.prof().capsule_pity_data or{})[db.STAR]or{}).total_opens)or 0)))
O.pickNote.skins=nil
elseif vo.open>0 then
local zo=vo.open>=10 and 10 or 1
local Ao=tonumber(G.cur(hlc[1600]))or 0
local Bo,Co=j.request(hlc[1645],hlc[1646],db.STAR,hlc[1394],hlc[1647],tostring(zo))
while L.now()-wo<5 and oo()<=0 do
task.wait(0.25)
end
if oo()<=0 then
return On(hlc[1648],wo,Co)
end
Q.add(string.format(hlc[1649],oo()),Ao-(tonumber(G.cur(hlc[1600]))or 0),hlc[1650],hlc[1651]..vo.why)
O.pickNote.skins=nil
else
break
end
end
end
end
