return zx.n
end
local Ax=0
pcall(function()
local Bx=G.Levels[wx]
local Cx=V.info(V.slim and V.slim(Bx)or Bx,hlc[1793]..yx)
local Dx=false
for Ex,Fx in pairs(Cx.configs or{})do
if xx[Ex]or(type(Fx)==hlc[1377]and xx[Fx.unit_id or hlc[306]])then
Dx=true
break
end
end
if not Dx then
