end
local Gx=Cx.infinite and math.floor(N.infReach(hlc[1521]..yx)+0.5)or Cx.total
local function Hx(Ix)
local Jx=Cx.configs[Ix]
return xx[Ix]or(type(Jx)==hlc[1377]and xx[Jx.unit_id or hlc[306]])
end
for Kx=1,math.min(Gx or 30,200)do
if Cx.infinite then
local Lx,Mx=pcall(G.LU.Infinite.infinite_amt_scale,Kx,Cx.ld)
local Nx,Ox=0,0
for Px,Qx in pairs(Cx.configs)do
if type(Qx)==hlc[1377]and Qx.spawn_tier_normal then
local Rx,Sx=pcall(G.LU.Infinite.infinite_get_normal_unit_chance,Qx,Kx)
Sx=Rx and tonumber(Sx)or 0
Nx=Nx+Sx
if Hx(Px)then
Ox=Ox+Sx
end
end
end
if Nx>0 then
Ax=Ax+(Lx and tonumber(Mx)or 10)*Ox/Nx
end
else
local Tx=Cx.list[Kx]
for Ux,Vx in ipairs(L.list(Tx and Tx.wave))do
if Hx(Vx.unit)then
Ax=Ax+(tonumber(Vx.amount)or 1)
end
end
end
end
Ax=math.floor(Ax+0.5)
end)
N._spawns[yx]={n=Ax,at=os.time()}
return Ax
end
function N.missionValue(Wx)
