for _x,ay in pairs(Xx and Xx.quest_handler.quest_profile_data.quests or{})do
local cy=ay.quest_info
local dy=cy and cy.quest_class
if dy and dy.class==hlc[1794]and type(dy.unit_ids)==hlc[1377]then
local ey=tonumber(dy.amount)or 0
local fy=ey-(tonumber(ay.quest_progress and ay.quest_progress.amount)or 0)
if fy>0 then
local gy=N.levelSpawns(Wx,dy.unit_ids)
if gy>0 then
local hy=tonumber(cy.quest_reward and cy.quest_reward.gem_reward)or 0
for iy,jy in pairs(cy.quest_reward and cy.quest_reward.item or{})do
if type(jy)==hlc[1377]and jy.item_id then
hy=hy+N.itemValue(jy.item_id,tonumber(jy.max_amount or jy.amount or jy.min_amount)or 1)
end
end
Yx=Yx+hy*math.min(1,gy/fy)
Zx=string.format(hlc[1795],tostring(cy.quest_name),L.fmt(ey-fy),L.fmt(ey),L.fmt(math.min(gy,fy)))
end
end
end
end
return Yx,Zx
end
