end
local mib=table.clone(cib)
mib.zone=true
local function nib(oib)
local pib=0
for qib,rib in ipairs({0.92,1,1.08})do
pib=pib+V.objective(V.run(oib,dib,{hpMul=eib*rib}))
end
return pib/3
end
local sib=nib(mib)-nib(cib)
if kib and sib> -V.ZONE_GAIN then
return true,hlc[2431],sib
end
if lib and sib>V.ZONE_GAIN then
return true,string.format(hlc[2432],eib),sib
end
return false,nil,sib
end
function V.strength(tib,uib)
local vib,wib,xib,yib,zib=V.teamFrom(uib,tib.map),0,0,0,0
for Aib,Bib in ipairs(V.LADDER)do
local Cib,Dib=0,0
for Eib,Fib in ipairs({0.92,1,1.08})do
local Gib=V.run(tib,vib,{hpMul=Bib*Fib})
if Gib.won then
Cib=Cib+1
end
Dib=Dib+Gib.wave
end
wib,zib=wib+Cib,Dib/3
if Bib==1 then
xib,yib=Cib,Dib/3
end
task.wait()
if Cib==0 then
break
end
end
return wib,xib,yib,zib
end
function V.bestTeam(Hib,Iib,Jib,Kib)
local Lib=L.now()
Kib=Kib or 25
local Mib=table.clone(Iib)
local Nib,Oib=V.cliff(Hib,V.teamFrom(Mib,Hib.map))
local function Pib(Qib)
local Rib=0
for Sib,Tib in ipairs(Qib)do
if M.isFarm(Tib.unit_id)then
Rib=Rib+1
end
end
return Rib
end
local Uib=Pib(Jib)>0
local function Vib(Wib)
local Xib=0
for Yib,Zib in ipairs(Wib)do
if not M.isFarm(Zib.unit_id)and not M.allyBuff(Zib.unit_id)then
Xib=Xib+M.cap(Zib)
end
end
return Xib
end
local _ib
while#Mib<6 do
local ajb,bjb
local cjb=Uib and Pib(Mib)==0
for djb,ejb in ipairs(Jib)do
local fjb=false
for gjb,hjb in ipairs(Mib)do
if hjb.unit_id==ejb.unit_id then
fjb=true
end
end
if not fjb and(not cjb or M.isFarm(ejb.unit_id))then
local ijb=table.clone(Mib)
table.insert(ijb,ejb)
local jjb=V.run(Hib,V.teamFrom(ijb,Hib.map),{hpMul=Nib})
local kjb=V.objective(jjb)
if not bjb or kjb>bjb then
ajb,bjb,_ib=ejb,kjb,jjb
end
end
end
if not ajb then
break
end
table.insert(Mib,ajb)
end
if Uib and Pib(Mib)==0 then
local ljb,mjb
for njb=1,#Mib do
for ojb,pjb in ipairs(Jib)do
if M.isFarm(pjb.unit_id)then
local qjb=table.clone(Mib)
qjb[njb]=pjb
local rjb=V.run(Hib,V.teamFrom(qjb,Hib.map),{hpMul=Nib})
local sjb=V.objective(rjb)
if not mjb or sjb>mjb then
ljb,mjb,_ib=qjb,sjb,rjb
end
end
end
end
if ljb then
Mib=ljb
end
end
local function tjb(ujb,vjb)
local wjb=V.teamFrom(ujb,Hib.map)
return(V.objective(vjb)+V.objective(V.run(Hib,wjb,{hpMul=Nib*0.92}))+V.objective(V.run(Hib,wjb,{hpMul=Nib*1.08})))/3
end
local xjb,yjb=_ib or Oib,tjb(Mib,_ib or Oib)
if type(Jib.rest)==hlc[1377]and#Jib.rest>0 then
local zjb,Ajb
for Bjb,Cjb in ipairs(Mib)do
if not M.isFarm(Cjb.unit_id)and not M.allyBuff(Cjb.unit_id)then
local Djb,Ejb=pcall(M.score,Cjb,Hib.mod)
Ejb=(Djb and Ejb or 0)*M.skinMul(Cjb,Hib.skinSet)
if not Ajb or Ejb<Ajb then
zjb,Ajb=Bjb,Ejb
end
end
end
if zjb then
local Fjb,Gjb={},L.now()
for Hjb,Ijb in ipairs(Jib.rest)do
if L.now()-Gjb>5 then
break
end
local Jjb=false
for Kjb,Ljb in ipairs(Mib)do
if Ljb.unit_id==Ijb.unit_id then
Jjb=true
end
end
if not Jjb then
local Mjb=table.clone(Mib)
Mjb[zjb]=Ijb
table.insert(Fjb,{u=Ijb,o=V.objective(V.run(Hib,V.teamFrom(Mjb,Hib.map),{hpMul=Nib}))})
end
end
table.sort(Fjb,function(Njb,Ojb)
return Njb.o>Ojb.o
end)
Jib=table.clone(Jib)
for Pjb=1,math.min(4,#Fjb)do
table.insert(Jib,1,Fjb[Pjb].u)
end
Lib=Lib+(L.now()-Gjb)
end
end
for Qjb=1,2 do
local Rjb=false
for Sjb=1,#Mib do
for Tjb,Ujb in ipairs(Jib)do
if L.now()-Lib>Kib then
return Mib,xjb,Nib,Oib
end
local Vjb=false
for Wjb,Xjb in ipairs(Mib)do
if Xjb.unit_id==Ujb.unit_id then
Vjb=true
end
end
if not Vjb then
local Yjb=table.clone(Mib)
Yjb[Sjb]=Ujb
if(not Uib or Pib(Yjb)>0)and Vib(Yjb)>=math.min(8,Vib(Mib))then
local Zjb=V.run(Hib,V.teamFrom(Yjb,Hib.map),{hpMul=Nib})
local _jb=V.objective(Zjb)
if _jb>yjb+1 then
_jb=tjb(Yjb,Zjb)
if _jb>yjb+1 then
Mib,yjb,xjb,Rjb=Yjb,_jb,Zjb,true
end
end
end
end
end
end
if not Rjb then
break
end
end
return Mib,xjb,Nib,Oib
end
function V.evolutions()
local akb=G.session()
local bkb,ckb={},{}
local dkb=akb.inventory
local function ekb(fkb)
local gkb=0
pcall(function()
gkb=dkb:get_number_of_owned_item(fkb)
end)
return gkb
end
for hkb,ikb in pairs(akb.profile_data.collection.owned_units)do
local jkb=G.Units[ikb.unit_id]
if jkb and jkb.evolve and jkb.evolve.evolve_unit and not jkb.evolve.hide_from_ui and not ckb[ikb.unit_id]and G.Units[jkb.evolve.evolve_unit]then
ckb[ikb.unit_id]=true
local kkb=ikb.shiny and jkb.evolve.shiny or jkb.evolve.normal
if kkb then
local lkb={}
for mkb,nkb in pairs(kkb.item_requirement or{})do
if ekb(nkb.item_id)<(nkb.amount or 1)then
table.insert(lkb,string.format(hlc[1811],(G.Items[nkb.item_id]or{}).name or nkb.item_id,ekb(nkb.item_id),nkb.amount))
end
end
for okb,pkb in pairs(kkb.unit_requirement or{})do
local qkb=0
for rkb,skb in pairs(akb.profile_data.collection.owned_units)do
if skb.unit_id==pkb.unit_id and(not pkb.shiny or skb.shiny)then
qkb=qkb+1
end
end
if qkb<(pkb.amount or 1)then
table.insert(lkb,string.format(hlc[1811],M.name(pkb.unit_id),qkb,pkb.amount))
end
end
local tkb=W.killsShort(akb.collection:get_unit_by_uuid(ikb.uuid)or ikb,kkb)
if tkb then
table.insert(lkb,string.format(hlc[2087],tkb.what,L.fmt(tkb.have),L.fmt(tkb.need)))
end
if#lkb<=1 then
local ukb=akb.collection:get_unit_by_uuid(ikb.uuid)or ikb
table.insert(bkb,{u=ukb,from=ikb.unit_id,to=jkb.evolve.evolve_unit,missing=lkb,evolved={unit_id=jkb.evolve.evolve_unit,uuid=hlc[1803]..tostring(ukb.uuid),xp=ukb.xp,traits=ukb.traits,trait_stats=ukb.trait_stats,further_modifiers=ukb.further_modifiers}})
end
end
end
end
return bkb
end
function V.levelFor(vkb)
local wkb=I.simCal[vkb.key]
if vkb.kind==hlc[1528]and I.live.daily and I.live.daily.ld then
return I.live.daily.ld,I.live.daily.challenge
end
if db.is(vkb.level)and I.live.event and I.live.event.ld then
return I.live.event.ld,nil
end
local xkb=vkb.kind~=hlc[1391]or(wkb and type(wkb.ld)==hlc[1377]and wkb.ld.id==vkb.level and wkb.ch==vkb.challenge)
if wkb and type(wkb.ld)==hlc[1377]and xkb then
return wkb.ld,wkb.ch
end
if vkb.kind==hlc[1391]and G.Levels[vkb.level]then
local ykb=V.slim(G.Levels[vkb.level])
ykb._difficulty=hlc[1562]
ykb._gamemode=hlc[1391]
ykb._challenge=vkb.challenge
return ykb,vkb.challenge
end
if G.Levels[vkb.level]then
local zkb=V.slim(G.Levels[vkb.level])
zkb._difficulty=vkb.diff
zkb._gamemode=zkb._OVERRIDE_GAMEMODE or(vkb.kind==hlc[1413]and hlc[1413])or(zkb.infinite and hlc[1396])or hlc[1412]
return zkb,nil
end
end
function V.plan(Akb,Bkb,Ckb,Dkb)
local Ekb,Fkb=V.levelFor(Akb)
if Akb.ldOverride then
Ekb=Akb.ldOverride
end
if not Ekb then
return nil
end
local Gkb=Akb.mod or(Akb.kind==hlc[1528]and I.live.daily and I.live.daily.mod)or N.levelMod(Akb.level)
local Hkb=V.info(Ekb,Akb.key,Fkb,Gkb)
local Ikb=Dkb
if not Ikb then
Ikb={}
for Jkb,Kkb in ipairs(M.equipped())do
table.insert(Ikb,Kkb.u)
end
end
local Lkb=V.teamFrom(Ikb,Hkb.map)
local Mkb=V.evaluate(Hkb,Lkb)
local Nkb,Okb=pcall(V.zoneChoice,Hkb,Lkb,Mkb.p>=0.92 and 1.7 or Mkb.p>=0.7 and 1.3 or 1,false)
if Nkb and Okb then
