Mkb.margin=Mkb.margin..hlc[2433]
end
Mkb.sig=V.sig(Ikb)
Mkb.trust=V.trust(Hkb,Lkb)
Mkb.label=Akb.label
Mkb.calibrated=(tonumber(Hkb.cal.n)or 0)>0
I.simRes[Akb.key]=Mkb
Mkb.aliveAt=nil
j.log(1,hlc[2434],string.format(hlc[2435],Akb.label,Mkb.margin,Mkb.calibrated and hlc[2436]or hlc[2437],Mkb.trust and string.format(hlc[2438],Mkb.trust.ratio)or hlc[2439]))
local Pkb=N.rec(Akb.key)
if H.simTeams and Bkb and type(Pkb.winTeam)==hlc[1377]and#Pkb.winTeam>0 then
local Qkb=G.session()
local Rkb={}
for Skb,Tkb in ipairs(Pkb.winTeam)do
local Ukb=Qkb.collection:get_unit_by_uuid(Tkb)
if Ukb then
table.insert(Rkb,Ukb)
end
end
if#Rkb== #Pkb.winTeam then
local Vkb=V.teamFrom(Rkb,Hkb.map)
local Wkb=V.run(Hkb,Vkb,{hpMul=1})
local Xkb=V.trust(Hkb,Vkb)
local Ykb=Xkb and not Xkb.ok
if not Wkb.won or Ykb then
local Zkb,_kb={},{}
for alb,blb in ipairs(Rkb)do
table.insert(Zkb,M.name(blb.unit_id))
table.insert(_kb,blb.unit_id)
end
I.simTeam[Akb.key]={uuids=Pkb.winTeam,names=Zkb,ids=_kb,won=true,wave=Hkb.total,better=V.sig(Rkb)~=Mkb.sig,cur={won=Mkb.won,wave=Mkb.wave},at=os.time(),label=Akb.label,base=Mkb.sig,why=hlc[2440]}
j.log(1,hlc[2434],string.format(hlc[2441],Akb.label,table.concat(Zkb,hlc[1472]),Ykb and string.format((Xkb.ratio or 0)<0.1 and hlc[2442]or hlc[2443],Xkb.ratio or 0)or string.format(hlc[2444],Wkb.wave),Pkb.winTeamN or 1))
return Mkb
end
end
end
if H.simTeams and Bkb then
local clb,dlb,elb,flb,glb=pcall(V.bestTeam,Hkb,Ikb,V.pool(Gkb,Hkb),Ckb)
if clb and dlb then
local hlb=V.sig(dlb)~=Mkb.sig
if hlb and Mkb.won and(Mkb.p or 0)>=0.92 then
local ilb={}
for jlb,klb in ipairs(dlb)do
table.insert(ilb,M.name(klb.unit_id))
end
j.log(1,hlc[2434],string.format(hlc[2445],Akb.label,table.concat(ilb,hlc[1472])))
dlb,hlb=Ikb,false
end
local llb=hlc[306]
if hlb then
local mlb,nlb=V.exam(Hkb,Ikb)
local olb,plb=V.exam(Hkb,dlb)
if olb>mlb or(olb==mlb and plb>nlb)then
llb=string.format(hlc[2446],olb,mlb)
else
local qlb={}
for rlb,slb in ipairs(dlb)do
table.insert(qlb,M.name(slb.unit_id))
end
j.log(1,hlc[2434],string.format(hlc[2447],Akb.label,table.concat(qlb,hlc[1472]),olb,mlb))
dlb,hlb=Ikb,false
end
end
local tlb=V.run(Hkb,V.teamFrom(dlb,Hkb.map),{hpMul=1})
if hlb then
Mkb.playing=tlb.won and hlc[2448]or string.format(hlc[2449],tlb.wave,Hkb.total)
end
local ulb,vlb={},{}
for wlb,xlb in ipairs(dlb)do
table.insert(ulb,xlb.uuid)
table.insert(vlb,M.name(xlb.unit_id))
end
local ylb={}
for zlb,Alb in ipairs(dlb)do
table.insert(ylb,Alb.unit_id)
end
I.simTeam[Akb.key]={uuids=ulb,names=vlb,ids=ylb,won=tlb.won,wave=tlb.wave,better=hlb,cur={won=Mkb.won,wave=Mkb.wave},at=os.time(),label=Akb.label,base=Mkb.sig}
j.log(1,hlc[2434],string.format(hlc[2450],Akb.label,tlb.won and hlc[1700]or(hlc[2451]..tlb.wave),table.concat(vlb,hlc[1472]),hlb and(string.format(hlc[2452],flb,elb.won and hlc[1700]or hlc[1701],elb.wave,glb.won and hlc[1700]or hlc[1701],glb.wave)..llb)or hlc[2453]))
local Blb={}
for Clb,Dlb in ipairs(V.evolutions())do
local Elb
if M.hidden(Dlb.from)or M.hidden(Dlb.to)then
Elb=hlc[1813]
else
local Flb=table.clone(dlb)
local Glb=false
for Hlb,Ilb in ipairs(Flb)do
if Ilb.unit_id==Dlb.from then
Flb[Hlb]=Dlb.evolved
Glb=true
end
end
if not Glb then
local Jlb,Klb=nil,math.huge
for Llb,Mlb in ipairs(Flb)do
if not M.isFarm(Mlb.unit_id)then
local Nlb,Olb=pcall(M.score,Mlb,Gkb)
if Nlb and Olb<Klb then
Jlb,Klb=Llb,Olb
end
end
end
if Jlb then
Flb[Jlb]=Dlb.evolved
end
end
local Plb=V.run(Hkb,V.teamFrom(Flb,Hkb.map),{hpMul=1})
if Plb.won and not tlb.won then
Elb=hlc[2454]..Akb.label..hlc[2455]
elseif Plb.wave>tlb.wave then
Elb=string.format(hlc[2456],Akb.label,Plb.wave,tlb.wave)
elseif Plb.won and tlb.won and Plb.t<tlb.t-6 then
Elb=string.format(hlc[2457],Akb.label,(tlb.t-Plb.t)/60)
else
Elb=tlb.won and(hlc[2458]..Akb.label..hlc[2459])or(hlc[2460]..Akb.label)
end
end
table.insert(Blb,{from=M.name(Dlb.from),to=M.name(Dlb.to),ready= #Dlb.missing==0,missing=Dlb.missing[1],gain=Elb,mode=Akb.label})
end
I.simEvo=Blb
end
end
j.saveSoon()
return Mkb
end
bb.T={CURSE=0,SHOP=1,MONEY=2,GOLD=3,CHEST=4,BOSS=5,OPEN=6,SHRINE=7}
