local jpb=bb.roomValue(ipb,_ob)
local kpb,lpb
for mpb,npb in ipairs(bb.after(Xob,ipb.choice))do
local opb=bb.roomValue(npb,_ob)
if not kpb or opb>kpb then
kpb,lpb=opb,npb
end
end
