bb.note(string.format(hlc[2529],sqb,#xqb>0 and table.concat(xqb,hlc[1472])or hlc[2530],#Dqb>0 and(hlc[2531]..table.concat(Dqb,hlc[1472]))or(sqb<10 and hlc[2532]or(Fqb>0 and hlc[2533]or hlc[2534])),tqb,Eqb>0 and string.format(hlc[2535],Eqb)or hlc[306],Fqb>0 and string.format(hlc[2536],Fqb,vqb)or hlc[306],yqb>0 and string.format(hlc[2537],yqb)or hlc[306]))
j.request(hlc[2538],hlc[2539])
