local Jub,Kub=Cub[Iub-1],Cub[Iub]
local Lub=(Kub-Jub).Magnitude
local Mub=math.max(1,math.floor(Lub/2))
for Nub=0,Mub-1 do
local Oub=Jub:Lerp(Kub,Nub/Mub)
table.insert(P.samples,{pos=Oub,prog=(Hub+Lub*Nub/Mub)/math.max(1,Fub),lane=Aub.Name})
end
Hub=Hub+Lub
end
if Cub[#Cub]then
table.insert(P.samples,{pos=Cub[#Cub],prog=1,lane=Aub.Name})
end
end
end
local Pub,Qub,Rub={},0,0
for Sub,Tub in ipairs(P.samples)do
local Uub=tostring(Tub.lane)
if not Pub[Uub]then
Qub=Qub+1
end
Pub[Uub]=(Pub[Uub]or 0)+1
Rub=Rub+1
end
P.laneCount={n=Qub,by=Pub,avg=Qub>0 and Rub/Qub or 1}
end
function P.buildWaves()
local Vub=P.ld
local Wub=Vub and Vub._dungeon and type(Vub._override_waves)==hlc[1377]and Vub._override_waves or nil
local Xub=Vub and G.Waves[(Wub and Wub.template)or Vub.waves or Vub.id]
local Yub
if type(Xub)==hlc[1377]then
Yub=Xub.override_waves or Xub.waves
if not Yub and Xub.template and G.Waves[Xub.template]then
Yub=G.Waves[Xub.template].waves or G.Waves[Xub.template].override_waves
end
end
P.waveList=L.list(Yub)
P.infinite=Vub and(Vub._gamemode==hlc[1396]or Vub.infinite)and V.unbound(Vub)or false
if P.infinite then
P.waveList={}
P.total=math.max(30,math.floor(N.infReach(P.key)+0.5))
return
end
P.total=(Vub and type(Vub._dungeon)==hlc[1377]and 15)or tonumber(Vub and Vub._override_infinite_bound_waves)or(#P.waveList>0 and#P.waveList)or 15
end
function P.infExtend()
if P.infinite and P.wave()+5>P.total then
P.total=P.wave()+10
end
end
function P.infWave(Zub)
P.infExtend()
if H.trainLeave and not P.stopping then
local _ub,avb=pcall(P.trainLeave,Zub)
if not _ub then
j.log(1,hlc[1907],hlc[2628]..tostring(avb))
end
end
if H.infiniteStop and not P.stopping then
local bvb,cvb=pcall(P.infStop,Zub)
if not bvb then
j.log(1,hlc[1907],hlc[2629]..tostring(cvb))
end
end
local dvb=N.infTier(Zub-1)
if dvb<=0 or dvb==P.infTierSeen then
return
end
P.infTierSeen=dvb
task.delay(5,function()
if not j.alive then
return
end
local evb=G.prof()
local fvb=evb and evb.daily_infinite_reward_claims and evb.daily_infinite_reward_claims[P.ld.id]
local gvb=type(fvb)==hlc[1377]and(tonumber(fvb.highest_claimed_wave)or 0)>=dvb and os.time()-(tonumber(fvb.highest_claim_time)or 0)<900
if gvb then
I.infLive=true
end
j.log(1,hlc[2630],string.format(hlc[2631],dvb,gvb and hlc[2632]or hlc[2633]))
end)
end
function P.infStop(hvb)
local ivb=0
for jvb,kvb in ipairs(L.list(G.GS.DAILY_INFINITE_REWARDS))do
ivb=math.max(ivb,tonumber(kvb.wave)or 0)
end
if ivb<=0 or hvb<=ivb+1 then
return
end
local lvb=I.train.on
if P.trainee and lvb and lvb.have+(lvb.got or 0)+(P.trainTk or 0)<lvb.need then
return
end
if not O.every(hlc[2634],60)then
return
end
local mvb=N.rec(P.key)
local nvb=tonumber(mvb.timed)or 0
local ovb=(nvb>0 and(mvb.sec or 0)>0)and math.max(0.5,((mvb.gems or 0)-200*nvb)/(mvb.sec/60))or 2.5
local pvb=pcall(N.pick)
local qvb
for rvb,svb in ipairs(pvb and N.lastScored or{})do
if svb.kind~=hlc[1396]and(not qvb or(svb.score or 0)>(qvb.score or 0))then
qvb=svb
end
end
if not qvb or(qvb.score or 0)<=ovb then
return
end
P.stopping=true
j.log(1,hlc[2630],string.format(hlc[2635],hvb,ovb,qvb.score,qvb.label))
P.sellAll()
end
function P.trainLeave(tvb)
local uvb=I.train.on
if not(P.infinite and P.trainee and uvb)then
return
end
P.trainCount()
local vvb=uvb.have+(uvb.got or 0)+(P.trainTk or 0)
if vvb<uvb.need then
return
end
local wvb,xvb,yvb=pcall(N.infDaily,G.prof(),P.ld.id,(N.infReach(P.key)))
if wvb and(xvb or 0)>0 and yvb>0 and tvb<=yvb then
j.status(hlc[2084],string.format(hlc[2636],M.name(uvb.id),uvb.what,yvb))
return
end
P.stopping=true
j.log(1,hlc[2630],string.format(hlc[2637],M.name(uvb.id),uvb.what,L.fmt(vvb),L.fmt(uvb.need),tvb))
P.sellAll()
end
function P.sellAll()
task.spawn(function()
local zvb={}
for Avb,Bvb in ipairs(P.mine or{})do
local Cvb=Bvb:FindFirstChild(hlc[1436])
local Dvb=Cvb and Cvb:FindFirstChild(hlc[2379])and G.Units[Cvb.id.Value]
