for fxb,gxb in ipairs(P.mine or{})do
local hxb=gxb:FindFirstChild(hlc[2660])
local ixb=hxb and hxb.Position or gxb:GetPivot().Position
local jxb=hxb and math.max(hxb.Size.X,hxb.Size.Z)/2 or 1.5
if(L.flat(dxb)-L.flat(ixb)).Magnitude<exb+jxb then
return nil
end
end
return dxb
end
function P.buildCandidates()
P.cands={}
local kxb={}
for lxb=1,#P.samples,3 do
local mxb=P.samples[lxb]
local nxb=P.samples[math.min(#P.samples,lxb+1)]
local oxb=L.flat(nxb.pos-mxb.pos)
if oxb.Magnitude<0.01 then
oxb=Vector3 .new(1,0,0)
end
oxb=oxb.Unit
local pxb=Vector3 .new(-oxb.Z,0,oxb.X)
for qxb,rxb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for sxb,txb in ipairs({1,-1})do
local uxb=mxb.pos+pxb*rxb*txb
local vxb=string.format(hlc[2659],math.floor(uxb.X/1.5),math.floor(uxb.Z/1.5))
if not kxb[vxb]then
kxb[vxb]=true
table.insert(P.cands,uxb)
end
end
end
end
end
function P.coverage(wxb,xxb)
local yxb={}
for zxb,Axb in ipairs(wxb)do
local Bxb=Axb._stats
if not M.isFarm(Bxb.id.Value)and Bxb:FindFirstChild(hlc[1513])then
table.insert(yxb,{p=L.flat(Axb:GetPivot().Position),r=Bxb.range.Value*(M.SUMMONER[Bxb.id.Value]and M.SUMMONER[Bxb.id.Value].reach or 1),air=P.canAir(Axb)})
end
end
local Cxb,Dxb=0,0
if#yxb>0 then
for Exb,Fxb in ipairs(P.samples)do
if Fxb.prog>Dxb then
local Gxb=L.flat(Fxb.pos)
for Hxb,Ixb in ipairs(yxb)do
if(Gxb-Ixb.p).Magnitude<=Ixb.r then
if Fxb.prog>Cxb then
Cxb=Fxb.prog
end
if Ixb.air then
Dxb=Fxb.prog
break
end
end
end
end
end
end
local Jxb,Kxb={},P.laneCount
if Kxb and Kxb.n>=2 and#yxb>0 then
local Lxb={}
for Mxb,Nxb in ipairs(P.samples)do
local Oxb=L.flat(Nxb.pos)
for Pxb,Qxb in ipairs(yxb)do
if(Oxb-Qxb.p).Magnitude<=Qxb.r then
local Rxb=tostring(Nxb.lane)
Lxb[Rxb]=(Lxb[Rxb]or 0)+1
if Nxb.prog>(Jxb[Rxb]or 0)then
Jxb[Rxb]=Nxb.prog
end
break
end
end
end
local Sxb,Txb={},0
for Uxb,Vxb in pairs(Kxb.by)do
Sxb[Uxb]=(Lxb[Uxb]or 0)/math.max(1,Vxb)
Txb=math.max(Txb,Sxb[Uxb])
end
P.laneW={}
for Wxb,Xxb in pairs(Kxb.by)do
P.laneW[Wxb]=(Kxb.avg/math.max(1,Xxb))*(1+1.5*(Txb>0 and(1-Sxb[Wxb]/Txb)or 0))
end
P.laneFrac=Sxb
else
P.laneW,P.laneFrac=nil,nil
end
local Yxb,Zxb,_xb
if#yxb>0 then
for ayb,byb in ipairs(xxb)do
local cyb=(P.laneW and byb.lane and Jxb[byb.lane])or Cxb
if byb.hp>0 and byb.prog>cyb+0.02 and byb.prog>(Yxb or 0)then
Yxb,_xb=byb.prog,P.laneW and byb.lane or nil
end
if byb.hp>0 and byb.fly and byb.prog>Dxb+0.02 then
Zxb=true
end
end
end
local dyb= #yxb>0 and(P.pressure or 0)>=Cxb-0.08
return{covEnd=Cxb,airEnd=Dxb,leak=Yxb,leakLane=_xb,covL=Jxb,airLeak=Zxb,push=dyb,units= #yxb}
end
function P.needLastLine(eyb)
