M._airFrom={}
function M.airFrom(syb)
local tyb=M._airFrom[syb]
if tyb~=nil then
return tyb or nil
end
local uyb=G.Units[syb]
if uyb and(uyb.hill_unit or uyb.hybrid_placement or M.SUMMONER[syb])then
M._airFrom[syb]=0
return 0
end
local vyb=M.rows(syb)
if not(vyb and vyb.max)then
return P.cardAir(syb)and 0 or nil
end
local wyb=false
for xyb=0,vyb.max do
local yyb=vyb[xyb]and vyb[xyb].atk
if yyb and G.Attacks[yyb]and G.Attacks[yyb].targets_flying then
wyb=xyb
break
end
end
if wyb==false and P.cardAir(syb)then
wyb=0
end
M._airFrom[syb]=wyb
return wyb or nil
end
function P.cardAir(zyb)
local Ayb=G.Units[zyb]
if not Ayb then
return false
end
if Ayb.hill_unit or Ayb.hybrid_placement then
return true
end
local Byb=M.field(zyb,hlc[1466])or M.field(zyb,hlc[1465])
return Byb and G.Attacks[Byb]and G.Attacks[Byb].targets_flying and true or false
