function P.airShare()
local Cyb,Dyb=0,0
for Eyb,Fyb in ipairs(P.mine or{})do
local Gyb=Fyb._stats.id.Value
if not M.isFarm(Gyb)then
local Hyb,Iyb=pcall(P.liveDps,Fyb,Gyb)
Iyb=Hyb and Iyb or 0
Cyb=Cyb+Iyb
if P.canAir(Fyb)then
Dyb=Dyb+Iyb
end
end
end
return Cyb>0 and Dyb/Cyb or 0
end
function P.cover(Jyb,Kyb,Lyb,Myb)
local Nyb=0
local Oyb=L.flat(Jyb)
local Pyb=Lyb and I.maps[P.mapKey()]and I.maps[P.mapKey()].dens
local Qyb=P.laneW
for Ryb,Syb in ipairs(P.samples)do
if(L.flat(Syb.pos)-Oyb).Magnitude<=Kyb then
local Tyb=1
if Pyb then
Tyb=0.15+0.85*(tonumber(Pyb[math.min(V.BINS,math.floor(Syb.prog*V.BINS)+1)])or 0)
end
if Qyb then
Tyb=Tyb*(Qyb[tostring(Syb.lane)]or 1)
end
if Myb then
if Myb.leak and Syb.prog>=Myb.leak-0.01 and(not Myb.leakLane or tostring(Syb.lane)==Myb.leakLane)then
Tyb=Tyb+3
elseif Myb.push and Syb.prog>Myb.covEnd then
Tyb=Tyb+0.6
end
end
Nyb=Nyb+Tyb
end
end
return Nyb
end
