j.log(1,hlc[2705],string.format(hlc[2714],M.name(yHb.id),P.spotKey(BHb),CHb,zHb))
P.placeLog=P.placeLog or{}
table.insert(P.placeLog,{t=math.floor(L.now()-(P.startT or L.now())),w=P.wave(),id=yHb.id,x=math.floor(BHb.X),z=math.floor(BHb.Z),cover=math.floor((CHb or 0)+0.5),why=tostring(zHb):sub(1,90)})
