if DHb>=(yHb.data.cost or 0)and P.random then
P.placeFail=P.placeFail or{}
P.placeFail[yHb.uuid]=(P.placeFail[yHb.uuid]or 0)+1
if P.placeFail[yHb.uuid]>=2 then
P.noSpot[yHb.uuid]=3
