local GHb=P.spotKey(BHb)
P.refused[GHb]=true
local HHb=P.mapKey()
I.blocked[HHb]=I.blocked[HHb]or{}
if not P.refusedRun[GHb]then
I.blocked[HHb][GHb]=(tonumber(I.blocked[HHb][GHb])or 0)+1
