for eIb,fIb in pairs(P.helperDealt)do
if fIb.owner==P.trialId then
dIb=dIb+fIb.v
end
end
table.insert(P.trialTrace,string.format(hlc[2720],THb,SHb-(P.startT or SHb),UHb,table.concat(WHb,hlc[1837]),YHb,XHb+dIb,#(P.enemies or{}),P.hpAliveRaw or 0,P.waveMax[THb-1]or 0,P.teamDps or 0))
end
