end
local hIb=UHb-(P.lastMoneyR or UHb)
P.lastMoneyR=UHb
P.incomeLog=P.incomeLog or{}
if hIb>0 then
table.insert(P.incomeLog,{t=SHb,y=hIb})
end
while P.incomeLog[1]and SHb-P.incomeLog[1].t>30 do
table.remove(P.incomeLog,1)
end
local iIb=0
for jIb,kIb in ipairs(P.incomeLog)do
iIb=iIb+kIb.y
end
local lIb=math.min(30,SHb-(P.startT or SHb))
P.incomeRate=lIb>=8 and iIb/lIb or nil
for mIb,nIb in ipairs(P.enemies)do
local oIb=nIb.m
local pIb=P.track[oIb]
if not pIb then
local qIb=oIb._stats
local rIb=oIb:FindFirstChildOfClass(hlc[2647])
local sIb=RHb.cfgById[qIb.id.Value]
local tIb=sIb and V.baseStats(RHb,sIb)
if rIb and tIb and THb>0 then
local uIb=tIb*RHb.hpRaw*V.waveScale(RHb,THb,RHb.list[THb])
if uIb>0 and rIb.MaxHealth>0 then
table.insert(QHb.hp,rIb.MaxHealth/uIb)
end
end
P.track[oIb]={t=SHb,p=nIb.prog,sp=(qIb:FindFirstChild(hlc[2722])and tonumber(qIb.speed.Value))or 1}
if THb>0 then
QHb.spawn[tostring(THb)]=(QHb.spawn[tostring(THb)]or 0)+1
QHb.spawnLast[tostring(THb)]=SHb-(QHb.lastWT or SHb)
end
elseif not pIb.done and SHb-pIb.t>=15 then
pIb.done=true
local vIb=(nIb.prog-pIb.p)/(SHb-pIb.t)/math.max(0.1,pIb.sp)
if vIb>0.001 and nIb.prog<0.95 then
table.insert(QHb.walk,vIb)
end
end
end
local wIb=0
for xIb,yIb in ipairs(P.mine)do
local zIb=yIb._stats:FindFirstChild(hlc[2723])
if zIb then
wIb=wIb+zIb.Value
end
end
QHb.potSum=QHb.potSum or 0
if QHb.lastDealtT then
local AIb=SHb-QHb.lastDealtT
local BIb=0
for CIb,DIb in ipairs(P.mine)do
