end
if not QHb.winT then
QHb.winT,QHb.winDealt=SHb,wIb
end
QHb.lastDealtT=SHb
if THb~=QHb.dpsW and THb>0 then
QHb.dpsAt[tostring(THb)]=P.teamDps or 0
QHb.dpsW=THb
end
local JIb=math.min(1,SHb-(QHb.densT or SHb))
QHb.densT=SHb
for KIb,LIb in ipairs(P.enemies)do
