local yQb=db.floor()
local zQb=(P.pressure or 0)>=H.safeReach or(P.depth and P.depth.leak)
local AQb=db.weatherStrength(db.weatherNow())
local BQb,CQb,DQb,EQb
local FQb={}
for GQb,HQb in pairs(wQb)do
local IQb,JQb=1,{}
for KQb,LQb in pairs(type(HQb)==hlc[1377]and HQb.effects or{})do
if type(LQb)==hlc[1377]then
local MQb=P.rogueEffect(LQb)
IQb=IQb*MQb
table.insert(JQb,P.effectText(LQb))
end
end
if type(HQb)==hlc[1377]and HQb.weather then
IQb=IQb*db.weatherStrength(HQb.weather)/math.max(0.05,AQb)
end
local NQb=type(HQb)==hlc[1377]and db.cardGems(HQb,xQb)or 0
local OQb=IQb>=1 or(P.fhP*IQb>=yQb and not zQb)
local PQb=math.log(math.max(0.05,IQb))*db.STRENGTH_GEMS+(OQb and NQb or-1000)
if not CQb or PQb>CQb then
BQb,CQb,DQb,EQb=GQb,PQb,IQb,NQb
end
table.insert(FQb,string.format(hlc[2817],tostring(GQb),tostring(type(HQb)==hlc[1377]and HQb.title or hlc[1590]),(type(HQb)==hlc[1377]and HQb.weather)and(hlc[1661]..tostring(HQb.weather)..hlc[1662])or hlc[306],tostring(type(HQb)==hlc[1377]and HQb.option_type or hlc[1590]),IQb,math.floor(NQb+0.5),table.concat(JQb,hlc[2471])))
end
return BQb,DQb,EQb,FQb,yQb,zQb
end
function P.huntPick(QQb)
local RQb=P.wave()
local SQb,TQb,UQb,VQb,WQb,XQb=P.huntChoose(QQb,RQb)
P.fhP=P.fhP*(TQb or 1)
P.rogueOptions=nil
local YQb,ZQb=pcall(E.JSONEncode,E,db.plain(QQb))
if YQb then
db.write(hlc[2818],string.format(hlc[2819],os.date(hlc[2282]),RQb,tostring(P.ld.map),tostring(db.weatherNow()),ZQb))
end
local _Qb=j.request(hlc[2820],hlc[2821],SQb)
j.log(1,hlc[2822],string.format(hlc[2823],RQb,tostring(SQb),math.floor((UQb or 0)+0.5),P.fhP,WQb,XQb and hlc[2824]or hlc[306],table.concat(VQb,hlc[2825])))
return _Qb
end
function P.huntRecord(aRb,bRb,cRb,dRb)
local eRb=db.floor()
I.hunt.pmin=L.clamp(eRb+(cRb and-0.1 or 0.1),0.4,2)
I.hunt.runs=I.hunt.runs or{}
table.insert(I.hunt.runs,1,{at=os.time(),wave=P.wave(),won=cRb or nil,pearls=bRb,mult=P.fhMult or 1,strength=P.fhP or 1,floor=eRb,map=P.ld.map,weather=db.weatherNow(),sec=dRb,picks=P.fhPicks})
while#I.hunt.runs>20 do
table.remove(I.hunt.runs)
end
local fRb=db.board()
j.log(1,hlc[2826],string.format(hlc[2827],cRb and hlc[1704]or hlc[1705],P.wave(),(tonumber(dRb)or 0)/60,bRb,P.fhMult or 1,tostring(P.ld.map),tostring(db.weatherNow()),fRb and string.format(hlc[2828],fRb.squares,#fRb.board)or hlc[306]))
local gRb={}
for hRb,iRb in ipairs({hlc[2829],hlc[2830],hlc[2831],hlc[2832],hlc[2833],hlc[2834],hlc[2835],hlc[2836]})do
if type(aRb)==hlc[1377]then
gRb[iRb]=aRb[iRb]
end
end
local jRb={}
for kRb in pairs(type(aRb)==hlc[1377]and aRb or{})do
table.insert(jRb,tostring(kRb))
end
table.sort(jRb)
local lRb,mRb=pcall(E.JSONEncode,E,db.plain(gRb))
if lRb then
db.write(hlc[2837],os.date(hlc[1576])..mRb..hlc[2838]..table.concat(jRb,hlc[1472]))
end
end
function P.pickRogue()
local nRb=P.rogueOptions
if nRb and P.hunt then
return P.huntPick(nRb)
end
if not nRb then
local oRb=j.request(hlc[2820],hlc[2821],1)
return oRb
end
P.fhP=P.fhP or 1
local pRb=tonumber(I.fh.pmin)or 1
local qRb=(P.pressure or 0)>=H.safeReach or(P.depth and P.depth.leak)
local rRb,sRb,tRb
for uRb,vRb in pairs(nRb)do
local wRb,xRb=1,0
for yRb,zRb in pairs(type(vRb)==hlc[1377]and vRb.effects or{})do
if type(zRb)==hlc[1377]then
local ARb,BRb=P.rogueEffect(zRb)
wRb=wRb*ARb
xRb=xRb+BRb
end
end
local CRb=math.log(math.max(0.05,wRb))*10
if xRb>0 and P.fhP*wRb>=pRb and not qRb then
CRb=CRb+100*xRb
elseif xRb>0 then
CRb=CRb-50+xRb
end
if not sRb or CRb>sRb then
rRb,sRb,tRb=uRb,CRb,wRb
end
end
P.fhP=P.fhP*(tRb or 1)
local DRb={}
for ERb,FRb in pairs(nRb)do
local GRb={}
for HRb,IRb in pairs(type(FRb)==hlc[1377]and FRb.effects or{})do
if type(IRb)==hlc[1377]then
table.insert(GRb,P.effectText(IRb))
end
end
table.insert(DRb,tostring(ERb)..hlc[2839]..table.concat(GRb,hlc[2471]))
end
P.rogueOptions=nil
local JRb=j.request(hlc[2820],hlc[2821],rRb)
j.log(1,hlc[2822],string.format(hlc[2840],P.wave(),tostring(rRb),sRb or 0,P.fhP,pRb,table.concat(DRb,hlc[2825])))
return JRb
end
function P.rogueShare(KRb)
if not KRb then
return 0.5
end
local LRb=tostring(KRb):gsub(hlc[2841],hlc[306])
local MRb,NRb=0,0
for ORb,PRb in ipairs(P.mine or{})do
local QRb=PRb._stats.id.Value
if not M.isFarm(QRb)then
local RRb,SRb=pcall(P.liveDps,PRb,QRb)
SRb=RRb and SRb or 0
local TRb=M.types(QRb)
MRb=MRb+SRb
if TRb[LRb]or TRb[LRb..hlc[2473]]then
NRb=NRb+SRb
end
end
end
local URb=0
for VRb,WRb in ipairs(P.mine or{})do
if not M.isFarm(WRb._stats.id.Value)then
URb=URb+1
end
end
local XRb=URb/(URb+4)
return XRb*(MRb>0 and NRb/MRb or 0.5)+(1-XRb)*0.5
end
function P.resistOf(YRb)
local ZRb=M.types(YRb)
local _Rb=0
for aSb,bSb in pairs(P.fhResist or{})do
local cSb=tostring(aSb):gsub(hlc[2841],hlc[306])
if ZRb[cSb]or ZRb[cSb..hlc[2473]]then
_Rb=math.max(_Rb,bSb/100)
end
end
return math.min(0.95,_Rb)
end
function P.rogueEffect(dSb)
local eSb,fSb,gSb=dSb.type,tonumber(dSb.amount)or 0,tostring(dSb.stat or hlc[306])
if eSb==hlc[1582]then
return 1,math.abs(fSb)
end
if eSb==hlc[2476]or eSb==hlc[2481]or eSb==hlc[2477]then
if gSb==hlc[1510]then
return math.max(0.3,1+fSb),0
end
if gSb==hlc[1513]then
return math.max(0.5,1+fSb/2),0
end
if gSb:find(hlc[2495])then
return 1/math.max(0.3,1+fSb),0
end
return 1,0
end
if eSb==hlc[2842]then
if gSb==hlc[1510]then
return math.max(0.3,fSb),0
end
if gSb==hlc[1513]then
return math.max(0.5,1+(fSb-1)/2),0
end
if gSb:find(hlc[2495])then
return 1/math.max(0.3,fSb),0
end
return 1,0
end
if eSb==hlc[2483]then
return 1+fSb/3,0
end
if eSb==hlc[2489]then
return 1/math.max(0.3,1+fSb),0
end
if eSb==hlc[2843]then
return math.max(0.2,1-P.rogueShare(dSb.damage_type)*(1-100/(100+fSb))),0
end
if eSb==hlc[2844]then
return 1+P.rogueShare(dSb.damage_type)*fSb,0
end
if eSb==hlc[2845]then
return math.max(0.5,1-fSb*0.5),0
end
if eSb==hlc[2846]then
return math.max(0.5,1-fSb*0.2),0
end
if eSb==hlc[2847]then
return 1+fSb*0.1,0
end
if eSb==hlc[2848]then
return 1/math.max(0.3,1+fSb*0.5),0
end
if eSb==hlc[2849]then
return math.max(0.5,1-fSb*0.1),0
end
if eSb==hlc[2484]then
return 1/math.max(0.3,1+fSb),0
end
if eSb==hlc[2490]then
return math.max(0.3,1-fSb*20),0
end
if eSb==hlc[2491]then
return math.max(0.5,1-fSb*0.03),0
end
if eSb==hlc[2850]then
return 0.95,0
end
if eSb==hlc[2492]then
return math.max(0.5,1-fSb),0
end
if eSb==hlc[2851]then
return 1+math.min(0.3,fSb/40000),0
end
if eSb==hlc[2485]then
return 1/math.max(0.3,1+fSb/2),0
end
if eSb==hlc[2852]then
return 0.8,0
end
if eSb==hlc[2853]then
local hSb=math.max(1,math.abs(fSb))*math.max(1,math.abs(tonumber(dSb.tier)or 1))
return dSb._type==hlc[2854]and 1.1^hSb or 0.8^hSb,0
end
return 1,0
end
function P.effectText(iSb)
return string.format(hlc[2855],tostring(iSb.type),iSb.stat and(hlc[1616]..tostring(iSb.stat))or hlc[306],tostring(iSb.amount))
end
function P.learn()
local jSb,kSb={},{}
local lSb,mSb=0,0
for nSb,oSb in ipairs(P.mine)do
local pSb=oSb._stats
local qSb=pSb.id.Value
local rSb=pSb:FindFirstChild(hlc[2723])and pSb.total_damage.Value or 0
if not M.isFarm(qSb)then
jSb[qSb]=(jSb[qSb]or 0)+rSb
kSb[qSb]=(kSb[qSb]or 0)+P.liveDps(oSb,qSb)/math.max(0.5,M.nudge(qSb))
local sSb=M.passive(qSb).mark
if sSb then
kSb[qSb]=kSb[qSb]+sSb.dot*pSb.damage.Value
end
lSb=lSb+rSb
end
end
for tSb,uSb in pairs(kSb)do
mSb=mSb+uSb
end
if lSb<=0 or mSb<=0 then
return
end
P.lastEff={}
for vSb,wSb in pairs(jSb)do
local xSb,ySb=wSb/lSb,kSb[vSb]/mSb
if ySb>0.02 then
local zSb=I.learn[vSb]or{eff=1,n=0}
local ASb=math.max(0.02,0.25*math.sqrt(30/(30+zSb.n)))
local BSb=L.clamp(xSb/ySb,0.3,3)
P.lastEff[vSb]=math.floor(BSb*1000+0.5)/1000
zSb.eff=zSb.eff+(BSb-zSb.eff)*ASb
zSb.n=zSb.n+1
I.learn[vSb]=zSb
end
end
end
function P.randomTeam()
local CSb=G.session()
local DSb=CSb and CSb.collection.temporary_units or{}
local ESb,FSb={},{}
local function GSb(HSb,ISb,JSb)
local KSb=HSb and DSb[HSb]
if KSb and G.Units[KSb.unit_id]and not FSb[HSb]then
FSb[HSb]=true
table.insert(ESb,{slot=JSb or 99,uuid=HSb,u=KSb,id=KSb.unit_id,data=G.Units[KSb.unit_id],hand=ISb})
end
end
for LSb,MSb in pairs(CSb and CSb.override_equipped_units or{})do
GSb(MSb,true,tonumber(LSb))
end
for NSb,OSb in ipairs(P.mine or{})do
local PSb=OSb._stats
GSb(PSb:FindFirstChild(hlc[2708])and PSb.uuid.Value,false)
end
table.sort(ESb,function(QSb,RSb)
return QSb.slot<RSb.slot
end)
return ESb
end
function P.fhSnap()
local SSb,TSb=nil,nil
pcall(function()
for USb,VSb in ipairs(workspace._BASES:GetDescendants())do
if VSb:IsA(hlc[2647])then
SSb,TSb=VSb.Health,VSb.MaxHealth
break
end
end
end)
local WSb=SSb and TSb and TSb>0 and math.floor(SSb/TSb*100)or-1
local XSb,YSb,ZSb=0,{},{}
for _Sb,aTb in ipairs(P.enemies or{})do
if(aTb.prog or 0)>0.8 then
XSb=XSb+1
YSb[tostring(aTb.m)]=(YSb[tostring(aTb.m)]or 0)+1
end
ZSb[tostring(aTb.m)]=(ZSb[tostring(aTb.m)]or 0)+1
end
if not next(YSb)then
YSb=ZSb
end
local bTb=0
for cTb,dTb in ipairs(P.mine or{})do
local eTb,fTb=pcall(P.liveDps,dTb,dTb._stats.id.Value)
if eTb and fTb then
bTb=bTb+fTb
end
end
P.fhWaves=P.fhWaves or{}
local gTb=0
for hTb,iTb in ipairs(P.enemies or{})do
if iTb.fly then
gTb=gTb+1
end
end
table.insert(P.fhWaves,string.format(hlc[2856],P.wave(),WSb,#(P.enemies or{}),XSb,L.fmt(bTb),P.fieldCount(),P.fhMult or 1,L.fmt(P.money()),math.floor(P.airShare()*100+0.5),gTb))
if WSb>=0 and P.fhLastPct and WSb<P.fhLastPct and not P.fhLeak then
local jTb={}
for kTb,lTb in pairs(YSb)do
table.insert(jTb,M.name(kTb)..hlc[2857]..lTb)
end
P.fhLeak=string.format(hlc[2858],P.wave(),P.fhLastPct,WSb,#jTb>0 and table.concat(jTb,hlc[1472])or hlc[2551])
j.log(1,hlc[2630],hlc[2859]..P.fhLeak)
end
P.fhLastPct=WSb
end
function P.fhRecord(mTb,nTb)
local oTb,pTb={},0
for qTb,rTb in ipairs(P.mine or{})do
local sTb=rTb._stats
local tTb=sTb:FindFirstChild(hlc[2723])and tonumber(sTb.total_damage.Value)or 0
local uTb=sTb.id.Value
if tTb>0 then
oTb[uTb]=(oTb[uTb]or 0)+tTb
pTb=pTb+tTb
end
end
local vTb={}
for wTb,xTb in pairs(oTb)do
local yTb=pTb>0 and xTb/pTb or 0
local zTb=I.fh.units[wTb]or{n=0,share=0}
zTb.share=(zTb.share*zTb.n+yTb)/(zTb.n+1)
zTb.n=zTb.n+1
I.fh.units[wTb]=zTb
table.insert(vTb,{id=wTb,share=yTb})
end
table.sort(vTb,function(ATb,BTb)
return ATb.share>BTb.share
end)
local CTb={}
for DTb=1,math.min(4,#vTb)do
table.insert(CTb,string.format(hlc[1697],M.name(vTb[DTb].id),math.floor(vTb[DTb].share*100+0.5)))
end
pcall(P.fhSnap)
local ETb=tonumber(I.fh.pmin)or 1
I.fh.pmin=L.clamp(ETb*(nTb and 0.9 or 1.1),0.5,2.5)
table.insert(I.fh.runs,1,{at=os.time(),wave=P.wave(),won=nTb or nil,coins=mTb,top=CTb,mult=P.fhMult or 1,discards=P.discards,strength=P.fhP,floor=ETb,effects=P.fhEffects,picks=P.fhPicks,leak=P.fhLeak,waves=P.fhWaves})
while#I.fh.runs>20 do
table.remove(I.fh.runs)
end
j.log(1,hlc[2860],string.format(hlc[2861],P.wave(),table.concat(CTb,hlc[1472])))
end
function P.carry(FTb)
