end
return string.format(hlc[2869]..hlc[2870]..hlc[2871],#HTb,VTb,ITb/ #HTb,math.floor(JTb/ #HTb+0.5),tostring(YTb.wave),tonumber(YTb.mult)or 1,tonumber(YTb.strength)or 1,YTb.leak and(hlc[2872]..YTb.leak)or hlc[306],table.concat(YTb.top or{},hlc[1472]),tonumber(I.fh.pmin)or 1,#RTb>0 and table.concat(RTb,hlc[1565])or hlc[2873],TTb,aUb)
end
function P.cardDps(eUb)
local fUb,gUb=pcall(M.dps,eUb.u,0,P.mod)
gUb=fUb and tonumber(gUb)or 0
if gUb>0 or M.isFarm(eUb.id)or M.idol(eUb.id)or M.allyBuff(eUb.id)then
return gUb
end
local hUb=table.clone(P.cardVals or{})
if#hUb==0 then
return 1000
end
table.sort(hUb)
return hUb[math.max(1,math.ceil(#hUb*0.6))]
end
function P.cardValue(iUb)
if M.isFarm(iUb.id)then
return 0
end
if M.idol(iUb.id)then
return(P.teamDps or 0)*P.idolStep()*3
end
local jUb=M.allyBuff(iUb.id)and P.buffGain(iUb)or P.cardDps(iUb)
return jUb*(1+2*P.carry(iUb.id))*(1-P.resistOf(iUb.id))*P.airNeed(iUb.id)*(P.mergeIds[iUb.id]and 2 or 1)
end
function P.flyMode()
if P.random or P.flyerSeen then
return true
end
if P.kind==hlc[1397]then
if P._curseFly==nil then
local kUb,lUb=pcall(bb.items,bb.data())
P._curseFly=kUb and(lUb._curse_fly or 0)>0 or false
end
return P._curseFly
end
return false
end
function P.shieldNow()
local mUb=P.wave()
if P._shieldW~=mUb then
P._shieldW,P._shieldS,P._shieldH=mUb,0,1
local nUb,oUb=pcall(V.wave,P.info,math.max(1,mUb),true)
if P.info and nUb and#oUb>0 then
local pUb,qUb=0,0
for rUb,sUb in ipairs(oUb)do
pUb,qUb=pUb+(sUb.sh or 0),qUb+sUb.hp
end
P._shieldS,P._shieldH=pUb/ #oUb,qUb/ #oUb
end
end
return P._shieldS,P._shieldH
end
function P.shieldOf(tUb,uUb)
local vUb,wUb=P.shieldNow()
if vUb<=0 or not uUb then
return tUb
end
local xUb=M.attackInfo(uUb.atk,uUb.range)
return U.shieldDps(tUb,tonumber(uUb.cd)or 2,xUb.n,vUb,wUb,P.info and P.info.eff,xUb.hits)
end
function P.shieldWork(yUb,zUb)
local AUb,BUb=P.shieldNow()
if AUb<=0 or not zUb or not P.info then
return 0
end
local CUb,DUb=0,0
for EUb,FUb in ipairs(P.team or{})do
local GUb=M.rows(FUb.id)
GUb=GUb and GUb[0]
if GUb and not M.isFarm(FUb.id)then
CUb=math.max(CUb,M.dps(FUb.u,0,P.mod)*(tonumber(GUb.cd)or 2)/math.max(1,M.attackInfo(GUb.atk,GUb.range).n))
end
